<a href="list.php" class="btnType1 black list">목록</a>            </div>        </div>    </div>    <!-- //subSec -->    </div>    <!-- //Container -->    <script>        document.addEventListener('DOMContentLoaded', function() {            // ===== 상수 및 변수 초기화 =====            // 슬라이더 초기화            const swiper = new Swiper(".eqDetail .img", {                pagination: { el: ".swiper-pagination" }            });            // 날짜 관련 변수            const today = new Date();            const applicationDays = <?= $arrSetInfo["list"][0]["place_application_days"] ?>;            const endDate = new Date();            endDate.setDate(today.getDate() + applicationDays);            // DOM 요소            const startTimeSelect = document.getElementById('rental_start_time');            const endTimeSelect = document.getElementById('rental_end_time');            const totalPriceElement = document.querySelector('.totalPrice .price');            const nameDateElement = document.querySelector('.totalPrice .nameDate');            // 설정값            const config = {                hourlyRate: <?=stripslashes($arrBoardArticle["list"][0]['fee'])?>,                maxAvailableHours: <?= $arrSetInfo["list"][0]["place_max_available_hours"] ?>,                subject: "<?=stripslashes($arrBoardArticle["list"][0]['subject'])?>",                usageLevel: "<?=stripslashes($arrBoardArticle["list"][0]['usage_level'])?>",                timeRanges: {                    lunch: {                        use: "<?= $arrSetInfo["list"][0]["place_lunch_use"] ?>",                        start: "<?= $arrSetInfo["list"][0]["place_lunch_start_time"] ?>",                        end: "<?= $arrSetInfo["list"][0]["place_lunch_end_time"] ?>"                    },                    dinner: {                        use: "<?= $arrSetInfo["list"][0]["place_dinner_use"] ?>",                        start: "<?= $arrSetInfo["list"][0]["place_dinner_start_time"] ?>",                        end: "<?= $arrSetInfo["list"][0]["place_dinner_end_time"] ?>"                    },                    rental: {                        use: "<?= $arrSetInfo["list"][0]["place_rental_use"] ?>",                        start: "<?= $arrSetInfo["list"][0]["place_rental_start_time"] ?>",                        end: "<?= $arrSetInfo["list"][0]["place_rental_end_time"] ?>"                    },                    return: {                        use: "<?= $arrSetInfo["list"][0]["place_return_use"] ?>",                        start: "<?= $arrSetInfo["list"][0]["place_return_start_time"] ?>",                        end: "<?= $arrSetInfo["list"][0]["place_return_end_time"] ?>"                    }                }            };            // 시간을 2자리 문자열로 포맷팅            function formatTime(hour) {                return String(hour).padStart(2, '0') + ':00';            }            // ===== 시간 선택 관련 함수 =====            // 시간 선택 옵션 생성            function populateTimeOptions(selectElement, range) {                const times = [];                // 9시부터 22시까지 시간 옵션 생성                for (let hour = 9; hour < 22; hour++) {                    const time = formatTime(hour);                    times.push(time);                }                // 초기 옵션 생성                selectElement.innerHTML = '<option value="">선택</option>';                // 시간 옵션 생성 (rental_end_time - 1 적용)                times.forEach(time => {                    const [hour] = time.split(':');                    if (                        parseInt(hour) <= (parseInt(config.timeRanges.rental.end) - 1) &&                        ((!range.use || range.use === 'N') || (time >= range.start && time <= range.end))                    ) {                        const option = document.createElement('option');                        option.value = time;                        option.textContent = time;                        selectElement.appendChild(option);                    }                });            }            // 종료 시간 옵션 업데이트            function updateEndTimeOptions() {                const startTime = startTimeSelect.value;                if (!startTime) return;                const startHour = parseInt(startTime.split(':')[0]);                endTimeSelect.innerHTML = '<option value="">선택</option>';                let maxEndHour = startHour + config.maxAvailableHours;                const lunchStartHour = parseInt(config.timeRanges.lunch.start);                const lunchEndHour = parseInt(config.timeRanges.lunch.end);                const dinnerStartHour = parseInt(config.timeRanges.dinner.start);                const dinnerEndHour = parseInt(config.timeRanges.dinner.end);                const returnEndHour = parseInt(config.timeRanges.return.end); // 반납 종료 시간 (18:00)                // 최대 종료 시간을 반납 종료 시간으로 제한                maxEndHour = Math.min(maxEndHour, returnEndHour);                // 시작 시간에 따른 종료 시간 계산                if (startHour === lunchStartHour) {                    maxEndHour = Math.min(lunchEndHour + config.maxAvailableHours, returnEndHour);                } else if (startHour === dinnerStartHour) {                    maxEndHour = Math.min(dinnerEndHour + config.maxAvailableHours, returnEndHour);                } else if (startHour < lunchStartHour && maxEndHour > lunchStartHour) {                    maxEndHour = Math.min(maxEndHour + 1, returnEndHour);                } else if (startHour < dinnerStartHour && maxEndHour > dinnerStartHour) {                    maxEndHour = Math.min(maxEndHour + 1, returnEndHour);                }                // 종료 시간 옵션 생성                for (let hour = startHour + 1; hour <= maxEndHour; hour++) {                    const timeOption = formatTime(hour);                    const option = document.createElement('option');                    option.value = timeOption;                    option.textContent = timeOption;                    endTimeSelect.appendChild(option);                }            }            // ===== 가격 계산 관련 함수 =====            function updateTotalPrice() {                if (!startTimeSelect?.value || !endTimeSelect?.value) return;                const startHour = parseInt(startTimeSelect.value);                const endHour = parseInt(endTimeSelect.value);                const lunchStart = parseInt(config.timeRanges.lunch.start);                const lunchEnd = parseInt(config.timeRanges.lunch.end);                const dinnerStart = parseInt(config.timeRanges.dinner.start);                const dinnerEnd = parseInt(config.timeRanges.dinner.end);                // 점심시간만 선택한 경우                if (startHour === lunchStart && endHour === lunchEnd) {                    resetPriceDisplay();                    return;                }                // 저녁시간만 선택한 경우                if (startHour === dinnerStart && endHour === dinnerEnd) {                    resetPriceDisplay();                    return;                }                // 총 선택된 시간                let totalHours = endHour - startHour;                // 실제 사용 가능한 시간 계산                let usableHours = totalHours;                // 점심시간 체크 (13:00~14:00)                if (startHour < lunchStart && endHour > lunchStart) {                    usableHours -= 1;                }                // 저녁시간 체크 (18:00~19:00)                if (startHour < dinnerStart && endHour > dinnerStart) {                    usableHours -= 1;                }                if (usableHours <= 0) {                    resetPriceDisplay();                    return;                }                const totalPrice = usableHours * config.hourlyRate;                updatePriceDisplay(totalPrice, usableHours);            }            function updatePriceDisplay(totalPrice, hours) {                totalPriceElement.textContent = `${totalPrice.toLocaleString()}원`;                nameDateElement.textContent = `${config.subject} / ${config.usageLevel} / (${hours}시간)`;                document.getElementById('total_price_hidden').value = totalPrice;                document.getElementById('usage_time_hidden').value = hours;            }            function resetPriceDisplay() {                totalPriceElement.textContent = '0원';                nameDateElement.textContent = `${config.subject} / ${config.usageLevel} / (0시간)`;                document.getElementById('total_price_hidden').value = 0;                document.getElementById('usage_time_hidden').value = 0;            }            // ===== 폼 제출 관련 함수 =====            window.submitRentalForm = function() {                // 필수 입력값 검증                const rentalDate = document.getElementById('st1').value;                if (!rentalDate) {                    alert('대관일을 선택해 주세요.');                    return;                }                if (!startTimeSelect.value) {                    alert('대관 시작 시간을 선택해 주세요.');                    return;                }                if (!endTimeSelect.value) {                    alert('대관 종료 시간을 선택해 주세요.');                    return;                }                // 시간 유효성 검증                const start = new Date(`1970-01-01T${startTimeSelect.value}`);                const end = new Date(`1970-01-01T${endTimeSelect.value}`);                if (end <= start) {                    alert('종료 시간이 시작 시간보다 빠를 수 없습니다.');                    return;                }                // 폼 제출                document.getElementById('rental_date').value = rentalDate;                document.getElementById('rentalForm').submit();            };            const minStartDate = new Date();            minStartDate.setDate(today.getDate() + 3);            const maxRentalEndDate = endDate + 3;            // ===== 초기화 및 이벤트 리스너 설정 =====            // DatePicker 초기화            $("#st1").datepicker({                showOn: "both",                buttonText: "날짜 선택",                prevText: '이전 달',                nextText: '다음 달',                monthNames: ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'],                monthNamesShort: ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'],                dayNames: ['일', '월', '화', '수', '목', '금', '토'],                dayNamesShort: ['일', '월', '화', '수', '목', '금', '토'],                dayNamesMin: ['일', '월', '화', '수', '목', '금', '토'],                dateFormat: 'yy-mm-dd',                showMonthAfterYear: true,                showAnim: false,                yearSuffix: '년',                minDate: minStartDate,                maxDate: maxRentalEndDate            });            // 시간 선택 옵션 초기화        populateTimeOptions(startTimeSelect, {            use: config.timeRanges.rental.use,            start: config.timeRanges.rental.start,            end: config.timeRanges.rental.end        });        populateTimeOptions(endTimeSelect, {            use: config.timeRanges.return.use,            start: config.timeRanges.return.start,            end: config.timeRanges.return.end        });            // 이벤트 리스너 등록            startTimeSelect.addEventListener('change', () => {                updateEndTimeOptions();                updateTotalPrice();            });            endTimeSelect.addEventListener('change', updateTotalPrice);        });    </script><?}###################################################### 사용자 페이지 ###################################################### END ?>